185	/// Every work run directory of a task's `work/` root, by sequence (`[]` when none). A
186	/// directory that holds no `run.json` is not a run.
187	pub fn run_dirs(work_root: &Path) -> Vec<(i64, PathBuf)> {
188	    let mut out: Vec<(i64, PathBuf)> = Vec::new();
189	    let rd = match std::fs::read_dir(work_root) {
190	        Ok(rd) => rd,
191	        Err(_) => return out,
192	    };
193	    for entry in rd.flatten() {
194	        let name = entry.file_name().to_string_lossy().to_string();
195	        let first = name.split('-').next().unwrap_or("");
196	        if first.is_empty() || !first.chars().all(|c| c.is_ascii_digit()) {
197	            continue;
198	        }
199	        let seq: i64 = first.parse().unwrap_or(0);
200	        if seq <= 0 || !entry.path().join("run.json").is_file() {
201	            continue;
202	        }
203	        out.push((seq, entry.path()));
204	    }
205	    out.sort_by_key(|(seq, _)| *seq);
206	    out
207	}
